mapper.select:
SELECT id, patient_id AS patientId, patient_name AS patientName, file_name AS fileName, file_type AS fileType, file_url AS fileUrl, upload_by AS uploadBy, upload_time AS uploadTime, download_count AS downloadCount FROM shared_file
AND patient_id = #{query.patientId}
AND patient_name LIKE CONCAT('%', #{query.patientName}, '%')
AND file_name LIKE CONCAT('%', #{query.fileName}, '%')
AND file_type = #{query.fileType}
AND upload_time >= #{query.uploadStartTime}
AND upload_time <= #{query.uploadEndTime}
ORDER BY upload_time DESC
